#include "estimate.h"
#include <QStringList>

int parseEstimate(const QString &text)
{
    if (text.isEmpty())
        return -1;

    int total = 0;
    const QStringList parts = text.split(' ', Qt::SkipEmptyParts);
    for (const QString &part : parts) {
        if (part.isEmpty())
            continue;

        QChar unit = part.back();
        QString numberPart = part.left(part.size() - 1);
        bool ok;
        int value = numberPart.toInt(&ok);
        if (!ok || value < 0)
            return -1;

        if (unit == 'w')
            total += value * 5 * 8 * 60;
        else if (unit == 'd')
            total += value * 8 * 60;
        else if (unit == 'h')
            total += value * 60;
        else if (unit == 'm')
            total += value;
        else
            return -1;
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return "";
    if (minutes == 0)
        return "0m";

    QStringList out;
    int remaining = minutes;

    int weeks = remaining / (5 * 8 * 60);
    if (weeks > 0) {
        out << QString::number(weeks) + "w";
        remaining %= (5 * 8 * 60);
    }

    int days = remaining / (8 * 60);
    if (days > 0) {
        out << QString::number(days) + "d";
        remaining %= (8 * 60);
    }

    int hours = remaining / 60;
    if (hours > 0) {
        out << QString::number(hours) + "h";
        remaining %= 60;
    }

    int mins = remaining;
    if (mins > 0) {
        out << QString::number(mins) + "m";
    }

    return out.join(' ');
}

